import re, io, contextlib
def _rerun(**over):
    src = __source__
    for k, v in over.items():
        src, n = re.subn(r'(?m)^' + k + r' = .*$', lambda m: k + ' = ' + repr(v), src, count=1)
        assert n == 1, k + ' satırı bulunamadı / line not found'
    ns = {'__name__': '__main__'}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        exec(compile(src, '<rerun>', 'exec'), ns)
    return ns, buf.getvalue()
ns, out = _rerun(order=["su"] * 12)
assert ns["receipt_no"] == "FIS-0012"

import re, io, contextlib
def _rerun(**over):
    src = __source__
    for k, v in over.items():
        src, n = re.subn(r'(?m)^' + k + r' = .*$', lambda m: k + ' = ' + repr(v), src, count=1)
        assert n == 1, k + ' satırı bulunamadı / line not found'
    ns = {'__name__': '__main__'}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        exec(compile(src, '<rerun>', 'exec'), ns)
    return ns, buf.getvalue()
ns, out = _rerun(order=["pasta", "su", "su"])
assert ns["unknown"] == {"pasta"}
assert ns["never_ordered"] == {"çay", "kahve", "tost", "simit"}
assert ns["summary"][:2] == (3, 2)
assert "Satılmayan: ['kahve', 'simit', 'tost', 'çay']" in out.splitlines()
